final class Cache(private var state: State) {      // one mutable reference

  def swapState(other: Cache): Unit = {            // plain rebinding: cannot fail
    val t = state
    state = other.state
    other.state = t
  }

  def commit(fresh: State): Unit = { state = fresh }
}
